const variants = { A: '轻量聊天', B: '游戏社交', C: '协作工作台' };
const contacts = [
  { name: '林间晚风', initials: '林', color: 'mint', preview: '今晚八点？我应该能准时上线', time: '14:32', status: '在线', game: 'Dota 2', count: 2 },
  { name: 'Morrow', initials: 'M', color: 'pink', preview: '图片已收到，画质不错', time: '14:18', status: '在线', game: 'Counter-Strike 2', count: 1 },
  { name: '小岛邮差', initials: '岛', color: 'yellow', preview: '给你看看我的新农场', time: '13:56', status: '在线', game: 'Stardew Valley' },
  { name: 'Northstar', initials: 'N', color: 'blue', preview: '好，那我们周末再约', time: '12:40', status: '离开' },
  { name: '白噪音', initials: '白', color: 'violet', preview: '这次更新终于修好了', time: '昨天', status: '离线' },
  { name: 'Echo', initials: 'E', color: 'peach', preview: '下次一起玩！', time: '昨天', status: '离线' }
];
let variant = new URLSearchParams(location.search).get('variant') || 'A';
if (!variants[variant]) variant = 'A';
let selected = 0;
let query = '';
let unreadOnly = false;
let mobileThread = false;
let infoOpen = false;
const messages = {};
const icon = name => `<i data-lucide="${name}" aria-hidden="true"></i>`;
const button = (name, title, cls = '', extra = '') => `<button class="icon-button ${cls}" title="${title}" aria-label="${title}" ${extra}>${icon(name)}</button>`;
const avatar = (c, cls = '') => `<span class="avatar ${c.color} ${cls}">${c.initials}<span class="presence ${c.status === '在线' ? 'online' : ''}"></span></span>`;
const safe = value => String(value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function account() { return `<button class="account-select" data-action="accounts"><span class="account-mark">${icon('gamepad-2')}</span><span><strong>Steam Chat</strong><small><span class="dot"></span> orbit · 已连接</small></span>${icon('chevrons-up-down')}</button>`; }
function rail(dark = false) { return `<aside class="rail"><div class="rail-logo">${icon('gamepad-2')}</div><div class="rail-top">${button('messages-square','聊天','selected')}${button('users','好友','','data-action="friends"')}${button('archive','历史会话','','data-action="history"')}</div><div class="rail-bottom">${button('settings-2','设置','','data-action="settings"')}<span class="self-avatar">O</span></div></aside>`; }
function list() {
  return `<aside class="conversations">${variant !== 'C' ? account() : ''}<div class="list-heading"><h2>${variant === 'B' ? '好友与聊天' : '消息'}</h2><span class="heading-count">6</span>${button('square-pen','新建会话','','data-action="new"')}</div><label class="search">${icon('search')}<input placeholder="搜索好友或会话" value="${safe(query)}" aria-label="搜索好友或会话"><span>⌘ K</span></label><div class="tabs"><button class="${!unreadOnly?'active':''}" data-filter="all">${variant === 'B'?'全部好友':'全部'} <span>6</span></button><button class="${unreadOnly?'active':''}" data-filter="unread">未读 <span>3</span></button><button data-action="groups">群组</button></div>${variant === 'B'?'<div class="list-section">在线好友 <span>3 / 6</span></div>':'<div class="list-section">最近会话<span>按最新消息</span></div>'}<div class="contact-list">${contactRows()}</div><div class="list-footer"><span class="dot"></span>${variant==='C'?'所有会话已同步':'Steam 网络已连接'}${icon('check-check')}</div></aside>`;
}
function contactRows() { const filtered = contacts.map((c,i)=>({...c,i})).filter(c=>(!unreadOnly||c.count)&&c.name.toLowerCase().includes(query.toLowerCase())); return filtered.length ? filtered.map(c=>`<button class="contact ${c.i===selected?'active':''}" data-contact="${c.i}">${avatar(c)}<span class="contact-copy"><span class="contact-first"><strong>${c.name}</strong><time>${c.time}</time></span><span class="contact-second">${variant==='B'&&c.game?`<span class="playing">${icon('gamepad-2')} ${c.game}</span>`:`<span>${c.preview}</span>`}${c.count?`<b class="unread">${c.count}</b>`:''}</span></span></button>`).join('') : '<div class="no-results">没有匹配的会话</div>'; }
function thread() { const c=contacts[selected];return `<main class="thread"><header class="thread-header">${button('arrow-left','返回会话列表','mobile-back','data-action="back"')}${avatar(c,'small')}<div class="thread-person"><h1>${c.name}</h1><span><span class="dot"></span>${c.status}${c.game?`<span class="separator">·</span>正在玩 ${c.game}`:''}</span></div><div class="thread-actions">${variant==='C'?'<span class="assignee">由我跟进</span>':''}${button('search','搜索当前会话','','data-action="thread-search"')}${button('panel-right','好友资料','','data-action="info"')}${button('ellipsis','更多操作','','data-action="more"')}</div></header>${variant==='C'?'<div class="context-strip"><span>当前账户 <strong>orbit</strong></span><span>好友会话</span><span class="context-right">已分配给 <strong>我</strong></span></div>':''}<div class="message-scroll"><div class="date-divider"><span>今天 · 9 月 7 日</span></div><div class="conversation-intro">${avatar(c,'intro-avatar')}<h3>${c.name}</h3><p>你们已是 Steam 好友</p></div><div class="message incoming">${avatar(c,'small')}<div class="message-body"><div class="message-meta"><strong>${c.name}</strong><time>14:28</time></div><div class="bubble">周末终于有空了，晚上要不要一起开黑？</div><div class="bubble consecutive">刚看到新活动，感觉可以试试。</div></div></div><div class="message outgoing"><div class="message-body"><div class="message-meta"><strong>我</strong><time>14:29</time></div><div class="bubble">好啊！我更新好了，随时可以。</div></div><span class="avatar own small">O</span></div><div class="message incoming">${avatar(c,'small')}<div class="message-body"><div class="message-meta"><strong>${c.name}</strong><time>14:30</time></div><div class="game-preview"><img src="./assets/dota.jpg" alt="Dota 2 游戏封面"><div><span class="preview-source">${icon('external-link')} STORE.STEAMPOWERED.COM</span><strong>Dota 2</strong><p>每一天，都有新的战场。</p></div></div><div class="bubble consecutive">今晚八点？我应该能准时上线</div></div></div><div class="message outgoing"><div class="message-body"><div class="message-meta"><strong>我</strong><time>14:32</time></div><div class="bubble">没问题，八点见！我再问问 Morrow。</div><span class="read-state">${icon('check-check')} 已发送至 Steam</span></div><span class="avatar own small">O</span></div><div id="sent-messages">${(messages[selected]||[]).map(text=>`<div class="message outgoing"><div class="message-body"><div class="bubble">${safe(text)}</div><span class="read-state">原型消息 · 仅本页可见</span></div><span class="avatar own small">O</span></div>`).join('')}</div></div><div class="composer-wrap"><form class="composer"><textarea rows="2" placeholder="发送消息给 ${c.name}…" aria-label="消息内容"></textarea><div class="composer-toolbar"><div>${button('smile','表情','','data-action="emoji"')}${button('paperclip','添加附件','','data-action="attach"')}${variant==='C'?'<span class="composer-account">以 orbit 发送</span>':''}</div><button type="submit" class="send-button">发送 ${icon('arrow-up')}</button></div><div class="emoji-picker" hidden><button type="button" data-emoji=":steamhappy:">:steamhappy:</button><button type="button" data-emoji=":heart:">:heart:</button><button type="button" data-emoji=":thumbsup:">:thumbsup:</button></div><input type="file" id="attachment" hidden></form><div class="composer-bottom"><span>${icon('lock-keyhole')} ${variant==='C'?'仅授权成员可查看此账户会话':'通过 Steam 好友消息发送'}</span><span>Steam Chat</span></div></div></main>`; }
function detail() {const c=contacts[selected];return `<aside class="details"><div class="detail-heading">好友资料 ${button('x','关闭资料','','data-action="info"')}</div><div class="profile">${avatar(c,'profile-avatar')}<h2>${c.name}</h2><p><span class="dot"></span>${c.status}</p><span class="profile-tag">Steam 好友</span></div><div class="detail-section"><h3>正在游戏中</h3><img class="detail-game" src="./assets/dota.jpg" alt="Dota 2"><strong>Dota 2</strong><p>游戏进行中</p></div><div class="detail-section"><h3>备注</h3><p>周末固定队友</p></div><div class="detail-section"><h3>共享链接 <span>2</span></h3><div class="shared-link"><img src="./assets/stardew.jpg" alt="Stardew Valley"><span>Stardew Valley<small>store.steampowered.com</small></span></div></div></aside>`;}
function teamnav() {return `<aside class="team-nav"><div class="team-brand">${icon('gamepad-2')}<strong>Steam Chat</strong><span>TEAM</span></div><div class="team-workspace"><span class="workspace-icon">O</span><span>Orbit 工作空间<small>3 位成员</small></span>${icon('chevrons-up-down')}</div><div class="team-nav-section"><small>工作空间</small><button class="active">${icon('inbox')}收件箱 <b>3</b></button><button data-action="friends">${icon('users')}好友</button><button data-action="history">${icon('clock-3')}历史记录</button></div><div class="team-nav-section"><small>Steam 账户 ${button('plus','添加账户','','data-action="accounts"')}</small><button class="account-row" data-action="accounts"><span class="dot"></span>orbit <span class="current-label">当前</span></button></div><div class="team-nav-section manage"><small>管理</small><button data-action="settings">${icon('contact-round')}成员与权限</button><button data-action="audit">${icon('scroll-text')}审计日志</button></div><div class="team-user"><span class="self-avatar">O</span><span>管理员<small>orbit workspace</small></span>${button('settings-2','设置','','data-action="settings"')}</div></aside>`;}
function render() {document.body.dataset.variant=variant;document.body.classList.toggle('mobile-thread',mobileThread);document.body.classList.toggle('info-open',infoOpen);document.getElementById('app').innerHTML=variant==='A'?`<div class="shell layout-a">${rail()}${list()}${thread()}${infoOpen?detail():''}</div>`:variant==='B'?`<div class="shell layout-b"><header class="gaming-top"><span class="gaming-brand">${icon('gamepad-2')} STEAM <b>CHAT</b></span><nav><button class="active" data-action="chat">聊天</button><button data-action="friends">好友动态</button><button data-action="games">游戏库</button></nav><div><span class="dot"></span>已连接 ${button('settings-2','设置','','data-action="settings"')}<span class="self-avatar">O</span></div></header><div class="gaming-workspace">${list()}${thread()}${detail()}</div></div>`:`<div class="shell layout-c">${teamnav()}<section class="team-main"><header class="team-header"><span>工作空间 <span>/</span> <strong>收件箱</strong></span><div><span class="demo-label">预览数据</span>${button('bell','通知','','data-action="notifications"')}</div></header><div class="team-body">${list()}${thread()}${infoOpen?detail():''}</div></section></div>`;document.getElementById('variant-label').textContent=`${variant} · ${variants[variant]}`;document.getElementById('previous').innerHTML=icon('arrow-left');document.getElementById('next').innerHTML=icon('arrow-right');lucide.createIcons();bind();console.info('Prototype state',{variant,selected:contacts[selected].name,unreadOnly,mobileThread,infoOpen});}
function switchVariant(step) {const keys=Object.keys(variants);variant=keys[(keys.indexOf(variant)+step+3)%3];const url=new URL(location.href);url.searchParams.set('variant',variant);history.replaceState({},'',url);infoOpen=false;render();}
function dialog(title,body) {document.querySelector('dialog')?.remove();const d=document.createElement('dialog');d.innerHTML=`<header><h2>${title}</h2>${button('x','关闭','','data-close')}</header>${body}`;document.body.append(d);d.querySelector('[data-close]').onclick=()=>d.close();d.addEventListener('click',e=>{if(e.target===d)d.close();});lucide.createIcons();d.showModal();return d;}
function bind() {
 document.querySelectorAll('[data-contact]').forEach(b=>b.onclick=()=>{selected=Number(b.dataset.contact);mobileThread=true;render();});
 document.querySelector('.search input').oninput=e=>{query=e.target.value;document.querySelector('.contact-list').innerHTML=contactRows();lucide.createIcons();document.querySelectorAll('[data-contact]').forEach(b=>b.onclick=()=>{selected=Number(b.dataset.contact);mobileThread=true;render();});};
 document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{unreadOnly=b.dataset.filter==='unread';render();});
 document.querySelector('.composer').onsubmit=e=>{e.preventDefault();const input=document.querySelector('textarea');if(!input.value.trim())return;(messages[selected]??=[]).push(input.value.trim());render();document.querySelector('.message-scroll').scrollTop=99999;};
 document.querySelectorAll('[data-emoji]').forEach(b=>b.onclick=()=>{document.querySelector('textarea').value+=b.dataset.emoji;document.querySelector('.emoji-picker').hidden=true;});
 document.querySelector('#attachment').onchange=e=>{if(e.target.files[0]){document.querySelector('textarea').value+=`[附件预览：${e.target.files[0].name}]`;}};
 document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>{const a=b.dataset.action;
 if(a==='back'){mobileThread=false;render();}else if(a==='info'){infoOpen=!infoOpen;document.body.classList.toggle('info-open',infoOpen);if(variant!=='B')render();}
 else if(a==='emoji')document.querySelector('.emoji-picker').hidden=!document.querySelector('.emoji-picker').hidden;
 else if(a==='attach')document.querySelector('#attachment').click();
 else if(a==='thread-search'){const d=dialog('搜索当前会话','<input class="dialog-input" placeholder="搜索消息内容"><div class="search-results"></div>');d.querySelector('input').oninput=e=>{const q=e.target.value.trim();d.querySelector('.search-results').textContent=q?Array.from(document.querySelectorAll('.bubble')).map(x=>x.textContent).filter(t=>t.includes(q)).join('\n')||'没有匹配的消息':'';};}
 else if(a==='new'||a==='friends'){const d=dialog('选择好友',`<div class="dialog-friends">${contacts.map((c,i)=>`<button data-pick="${i}">${avatar(c)}<span>${c.name}<small>${c.status}</small></span>${icon('arrow-up-right')}</button>`).join('')}</div>`);d.querySelectorAll('[data-pick]').forEach(x=>x.onclick=()=>{selected=Number(x.dataset.pick);mobileThread=true;d.close();render();});}
 else if(a==='accounts')dialog('Steam 账户','<div class="account-dialog"><span class="self-avatar">O</span><div><strong>orbit</strong><p>已连接 · 当前活动账户</p></div><span class="dot"></span></div><p class="dialog-note">原型使用模拟账户，不会连接 Steam。</p>');
 else if(a==='groups')dialog('群组','<p class="dialog-note">群聊收发尚未开放。</p>');
 else if(a==='games')dialog('游戏库',`<div class="game-library">${['dota','cs2','stardew'].map((g,i)=>`<img src="./assets/${g}.jpg" alt="${['Dota 2','Counter-Strike 2','Stardew Valley'][i]}">`).join('')}</div>`);
 else if(a==='chat'){mobileThread=false;render();}
 else dialog({settings:'设置',audit:'审计日志',history:'历史记录',notifications:'通知',more:'会话操作'}[a]||'预览','<p class="dialog-note">此原型仅展示聊天界面，管理功能沿用现有后台。</p>');
 });
}
document.getElementById('previous').onclick=()=>switchVariant(-1);document.getElementById('next').onclick=()=>switchVariant(1);
document.addEventListener('keydown',e=>{if(e.target.closest('input,textarea,[contenteditable]')||document.querySelector('dialog[open]'))return;if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();switchVariant(e.key==='ArrowLeft'?-1:1);}});
render();
